architecture.h4_f:
msg = CBOR{v:1، دەق، وەڵام_بۆ، نێردراو_لە}
ct = AES-GCM-256-کۆدکردن (k، nonce، msg، aad = room_id)
POST /api/ژوورەکان/{id}/نامە {ciphertext: hex(ct), nonce: hex}

cryptoWire.h1_f:
pt = CBOR{v:1، دەق، وەڵام_بۆ؟، ناسنامەی_تەوەرە؟، باسکردن؟، نێردراو_لە}
ct = AES-GCM-256-کۆدکردن (کلیلی_ژوور، nonce، pt، aad=hex (ئایدی ژوور))
وایەر = CBOR{
  v: 1،
  ciphertext: hex(ct)، // درێژی گۆڕاو
  nonce: هێکس(12 B)،
  ساختەی_نێرەر: hex(16 B)،
  sent_at: unix_ms
}

cryptoWire.h5_f:
دەرەوە = CBOR{
  سەرچاوە_گرێ: hex32,
  بەکارهێنەری_ئامانج: int64,
  inner_ciphertext: بایتەکان،
  inner_nonce: بایتەکان،
  sent_at: unix_ms
}
sig = Ed25519-Sign (سەرچاوە_priv، دەرەوە)
POST /فیدراسیۆن/گەیاندن { زەرف: دەرەوە، سیگ: hex64 }

auth.h1_f:
