                    هەڵبژاردنەکان = { rp.id، user.id، pubKeyCredParams، تەحەدا }
                    هەڵبژاردەکانی گەڕانەوە

register_finish(سەلماندن):
  پشتڕاستکردنەوەی ئیسپاتی دژی TPM / ڕەگی Enclave پارێزراو CA
  store { ناسنامەی_ناسنامە، کلیلی_گشتی، ژمێریار: 0 }

auth.h7_f:
POST /api/ڕەسەنایەتی/qr/دەستپێکردن
  → { nonce: هێکسی ١٢٨ بیتی، ttl: ٦٠ }
QR payload = { جارێک، ناسنامەی بەکارهێنەر، سێرڤەر: "https://node.example" }

POST /api/ڕەسەنایەتی/qr/دڵنیاکردنەوە { nonce }
  → ئامێری نوێ تۆمارکراوە؛ JWTs گەڕانەوە.

rooms.h6_f:
sender_pseudo = HMAC-SHA256(خوێی ساختەی ژوور، ناسنامەی_نێرەر)[:16] // 32 هێکس
ciphertext = AES-GCM-کۆدکردن(کلیلی_ژوور، جارێک، CBOR_payload، aad=ئایدی_ژوور)

چوارچێوەی هەواگۆڕکێ: { جۆر:"m", ژوور, msg:{id, ct, nonce, sender_pseudo, sent_at} }

